const listBillableShipments = `-- name: ListBillableShipments :many

SELECT s.id, s.public_id, s.awb, s.booked_at, s.chargeable_weight_grams,
       s.origin_pincode, s.destination_pincode, s.currency,
       cs.id AS charge_snapshot_id,
       cs.freight_minor, cs.surcharge_total_minor, cs.discount_total_minor,
       cs.taxable_minor, cs.tax_total_minor, cs.rounding_minor, cs.total_minor,
       cs.line_items
FROM shipments s
JOIN shipment_charge_snapshots cs ON cs.shipment_id = s.id
LEFT JOIN shipment_commercial_snapshots commercial ON commercial.shipment_id = s.id AND commercial.organization_id = s.organization_id
LEFT JOIN invoice_shipments inv ON inv.shipment_id = s.id
WHERE s.organization_id = $1
  AND (CASE WHEN commercial.shipment_id IS NULL THEN s.customer_id ELSE commercial.transport_customer_id END) = $2
  AND s.payment_mode IN ('CREDIT','PREPAID')
  AND s.current_status NOT IN ('CANCELLED')
  AND s.booked_at >= $3::timestamptz
  AND s.booked_at < $4::timestamptz
  AND inv.id IS NULL
ORDER BY s.booked_at, s.id
LIMIT $5
FOR UPDATE OF s
`

type ListBillableShipmentsParams struct {
	OrganizationID int64
	CustomerID     int64
	PeriodStart    time.Time
	PeriodEnd      time.Time
	Limit          int32
}

type ListBillableShipmentsRow struct {
	ID                    int64
	PublicID              string
	Awb                   string
	BookedAt              time.Time
	ChargeableWeightGrams int32
	OriginPincode         string
	DestinationPincode    string
	Currency              string
	ChargeSnapshotID      int64
	FreightMinor          int64
	SurchargeTotalMinor   int64
	DiscountTotalMinor    int64
	TaxableMinor          int64
	TaxTotalMinor         int64
	RoundingMinor         int64
	TotalMinor            int64
	LineItems             []byte
}

// ---------------------------------------------------------------------------
// Billable shipments
// ---------------------------------------------------------------------------
// Delivered shipments for a customer in a window that have not been invoiced.
//
// The charge snapshot is joined here rather than the rate card: the snapshot is
// what the shipment was actually priced at, and it is immutable. Billing from a
// live rate card would let a rate change alter an old invoice.
//
// FOR UPDATE OF s so a concurrent billing run for the same customer blocks
// rather than invoicing the same shipments twice.
func (q *Queries) ListBillableShipments(ctx context.Context, arg ListBillableShipmentsParams) ([]ListBillableShipmentsRow, error) {
	rows, err := q.db.Query(ctx, listBillableShipments,
		arg.OrganizationID,
		arg.CustomerID,
		arg.PeriodStart,
		arg.PeriodEnd,
		arg.Limit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListBillableShipmentsRow{}
	for rows.Next() {
		var i ListBillableShipmentsRow
		if err := rows.Scan(
			&i.ID,
			&i.PublicID,
			&i.Awb,
			&i.BookedAt,
			&i.ChargeableWeightGrams,
			&i.OriginPincode,
			&i.DestinationPincode,
			&i.Currency,
			&i.ChargeSnapshotID,
			&i.FreightMinor,
			&i.SurchargeTotalMinor,
			&i.DiscountTotalMinor,
			&i.TaxableMinor,
			&i.TaxTotalMinor,
			&i.RoundingMinor,
			&i.TotalMinor,
			&i.LineItems,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

