const markOverdueInvoices = `-- name: MarkOverdueInvoices :exec
UPDATE invoices
   SET status = 'OVERDUE'
 WHERE organization_id = $1
   AND status IN ('ISSUED','PARTIALLY_PAID')
   AND due_date < current_date
`

// Run by the worker. Moves past-due invoices into OVERDUE so the collections
// queue is a query rather than a date comparison in every caller.
func (q *Queries) MarkOverdueInvoices(ctx context.Context, organizationID int64) error {
	_, err := q.db.Exec(ctx, markOverdueInvoices, organizationID)
	return err
}

