const sumInvoiceLines = `-- name: SumInvoiceLines :one
SELECT
    COALESCE(SUM(amount_minor), 0)::bigint   AS amount_minor,
    COALESCE(SUM(discount_minor), 0)::bigint AS discount_minor,
    COALESCE(SUM(taxable_minor), 0)::bigint  AS taxable_minor,
    COALESCE(SUM(tax_minor), 0)::bigint      AS tax_minor,
    COALESCE(SUM(total_minor), 0)::bigint    AS total_minor,
    count(*)::bigint                          AS line_count
FROM invoice_lines
WHERE invoice_id = $1
`

type SumInvoiceLinesRow struct {
	AmountMinor   int64
	DiscountMinor int64
	TaxableMinor  int64
	TaxMinor      int64
	TotalMinor    int64
	LineCount     int64
}

func (q *Queries) SumInvoiceLines(ctx context.Context, invoiceID int64) (SumInvoiceLinesRow, error) {
	row := q.db.QueryRow(ctx, sumInvoiceLines, invoiceID)
	var i SumInvoiceLinesRow
	err := row.Scan(
		&i.AmountMinor,
		&i.DiscountMinor,
		&i.TaxableMinor,
		&i.TaxMinor,
		&i.TotalMinor,
		&i.LineCount,
	)
	return i, err
}

const sumInvoicePayments = `-- name: SumInvoicePayments :one
SELECT COALESCE(SUM(amount_minor) FILTER (WHERE status IN ('RECORDED','CONFIRMED')), 0)::bigint
           AS paid_minor,
       count(*)::bigint AS payment_count
FROM invoice_payments
WHERE invoice_id = $1
`

type SumInvoicePaymentsRow struct {
	PaidMinor    int64
	PaymentCount int64
}

func (q *Queries) SumInvoicePayments(ctx context.Context, invoiceID int64) (SumInvoicePaymentsRow, error) {
	row := q.db.QueryRow(ctx, sumInvoicePayments, invoiceID)
	var i SumInvoicePaymentsRow
	err := row.Scan(&i.PaidMinor, &i.PaymentCount)
	return i, err
}
